const COLLAPSED_ROW_COUNT = 1;
const MAX_VISIBLE_ROWS_EXPANDED = 2;

const AboutFilmGallery = () => {
  const gridRef = useRef(null);
  const viewportRef = useRef(null);
  const [columnCount, setColumnCount] = useState(3);
  const [expanded, setExpanded] = useState(false);
  const [viewportMaxPx, setViewportMaxPx] = useState(null);
  const [scrollStepPx, setScrollStepPx] = useState(240);
  const [canScrollUp, setCanScrollUp] = useState(false);
  const [canScrollDown, setCanScrollDown] = useState(false);
  const [showScrollControls, setShowScrollControls] = useState(false);

  const syncScrollState = useCallback(() => {
    const v = viewportRef.current;
    if (!v) return;
    const { scrollTop, scrollHeight, clientHeight } = v;
    const slack = 4;
    setCanScrollUp(scrollTop > slack);
    setCanScrollDown(scrollTop + clientHeight < scrollHeight - slack);
    setShowScrollControls(scrollHeight > clientHeight + slack);
  }, []);

  const measureExpandedViewport = useCallback(() => {
    const grid = gridRef.current;
    const viewport = viewportRef.current;
    if (!grid || !expanded) return;
    if (viewport) viewport.scrollTop = 0;
    const children = [...grid.children];
    if (children.length === 0) return;

    const template = window.getComputedStyle(grid).gridTemplateColumns;
    const colCount = Math.max(1, template.split(/\s+/).filter(Boolean).length);
    const firstRowTop = children[0].offsetTop;
    const thirdRowFirstIndex = colCount * MAX_VISIBLE_ROWS_EXPANDED;

    if (children.length <= thirdRowFirstIndex) {
      setViewportMaxPx(grid.scrollHeight);
    } else {
      const thirdRowTop = children[thirdRowFirstIndex].offsetTop;
      const clipPx = thirdRowTop - firstRowTop;
      // Floor + 1px margin: subpixel layout/DPR can otherwise show a hairline of the next row.
      setViewportMaxPx(Math.max(0, Math.floor(clipPx) - 1));
    }

    if (children.length > colCount) {
      setScrollStepPx(Math.max(40, Math.round(children[colCount].offsetTop - firstRowTop)));
    } else {
      setScrollStepPx(Math.max(40, Math.round(grid.scrollHeight)));
    }
  }, [expanded]);

  const onGridLayout = useCallback(() => {
    const el = gridRef.current;
    if (!el) return;
    const template = window.getComputedStyle(el).gridTemplateColumns;
    const count = template.split(/\s+/).filter(Boolean).length;
    setColumnCount(count > 0 ? count : 1);
    measureExpandedViewport();
  }, [measureExpandedViewport]);

  useLayoutEffect(() => {
    const el = gridRef.current;
    if (!el) return undefined;
    onGridLayout();
    const ro = new ResizeObserver(onGridLayout);
    ro.observe(el);
    window.addEventListener('resize', onGridLayout);
    return () => {
      ro.disconnect();
      window.removeEventListener('resize', onGridLayout);
    };
  }, [onGridLayout, expanded]);

  useLayoutEffect(() => {
    if (!expanded) {
      setViewportMaxPx(null);
      return;
    }
    requestAnimationFrame(() => {
      measureExpandedViewport();
      syncScrollState();
      requestAnimationFrame(() => {
        measureExpandedViewport();
        syncScrollState();
      });
    });
  }, [expanded, measureExpandedViewport, syncScrollState]);

  const collapsedCap = Math.min(FILM_PHOTO_URLS.length, columnCount * COLLAPSED_ROW_COUNT);
  const hasMore = FILM_PHOTO_URLS.length > collapsedCap;
  const collapsedUrls = FILM_PHOTO_URLS.slice(0, collapsedCap);

  const scrollViewportByRows = (direction) => {
    const v = viewportRef.current;
    if (!v) return;
    v.scrollBy({ top: direction * scrollStepPx, behavior: 'smooth' });
  };

  const blockFilmImageUi = (e) => {
    e.preventDefault();
  };

  const gridContent = (urls, eagerUpTo) => (
    <FilmGrid ref={gridRef} onContextMenu={blockFilmImageUi}>
      {urls.map((src, i) => (
        <FilmImage
          key={src}
          src={src}
          alt=""
          loading={i < eagerUpTo ? 'eager' : 'lazy'}
          draggable={false}
          onDragStart={blockFilmImageUi}
        />
      ))}
    </FilmGrid>
  );

  return (
    <FilmSection aria-label="Film photography gallery">
      <FilmGalleryBubbleRow>
        <FilmGalleryBubble>
          {!expanded
            ? gridContent(collapsedUrls, collapsedCap)
            : (
                <FilmGalleryViewport
                  ref={viewportRef}
                  style={viewportMaxPx != null ? { maxHeight: viewportMaxPx } : undefined}
                  onScroll={syncScrollState}
                >
                  {gridContent(FILM_PHOTO_URLS, columnCount * MAX_VISIBLE_ROWS_EXPANDED)}
                </FilmGalleryViewport>
              )}
          {expanded && (
            <FilmExpandedControls>
              {showScrollControls && (
                <FilmScrollArrowsGroup>
                  <FilmScrollArrowButton
                    type="button"
                    aria-label="Scroll up"
                    disabled={!canScrollUp}
                    onClick={() => scrollViewportByRows(-1)}
                  >
                    ↑
                  </FilmScrollArrowButton>
                  <FilmScrollArrowButton
                    type="button"
                    aria-label="Scroll down"
                    disabled={!canScrollDown}
                    onClick={() => scrollViewportByRows(1)}
                  >
                    ↓
                  </FilmScrollArrowButton>
                </FilmScrollArrowsGroup>
              )}
              <FilmToggleHalfButton type="button" onClick={() => setExpanded(false)}>
                Show less
              </FilmToggleHalfButton>
            </FilmExpandedControls>
          )}
          {!expanded && hasMore && (
            <FilmToggleRow>
              <FilmToggleFullButton type="button" onClick={() => setExpanded(true)}>
                Show more
              </FilmToggleFullButton>
            </FilmToggleRow>
          )}
        </FilmGalleryBubble>
      </FilmGalleryBubbleRow>
    </FilmSection>
  );
};

